('bmlt-csf-bodyfluids-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',2104,$json${"question":"A markedly low CSF glucose is classically associated with:","translation":"","options":["Bacterial meningitis","Migraine","Simple dehydration","Iron deficiency"],"correctIndex":0,"explanation":"Bacterial meningitis commonly lowers CSF glucose; TB and fungal meningitis may also do so.","explanationNe":"Bacterial meningitis मा CSF glucose प्रायः घट्छ; TB र fungal meningitis मा पनि घट्न सक्छ।","topic":"CSF and Body Fluid Analysis"}$json$::jsonb,true),
('bmlt-csf-bodyfluids-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',2105,$json${"question":"A traumatic tap may cause:","translation":"","options":["RBC contamination of CSF","False absence of protein","Sterile urine","Low serum sodium"],"correctIndex":0,"explanation":"Needle trauma can introduce peripheral blood into the CSF sample.","explanationNe":"Needle ले चोट पुर्‍याउँदा रगत CSF मा मिसिन सक्छ।","topic":"CSF and Body Fluid Analysis"}$json$::jsonb,true),
('bmlt-csf-bodyfluids-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',2106,$json${"question":"Xanthochromia means:","translation":"","options":["Yellow discoloration of CSF","Green discoloration of urine","Cloudy serum","Colorless plasma"],"correctIndex":0,"explanation":"Xanthochromia is yellow or yellow-orange CSF discoloration, often from bilirubin.","explanationNe":"Xanthochromia भनेको CSF पहेँलो देखिनु हो, जुन bilirubin का कारण हुन सक्छ।","topic":"CSF and Body Fluid Analysis"}$json$::jsonb,true),
