('bmlt-csf-bodyfluids-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',2111,$json${"question":"Urine specific gravity mainly reflects:","translation":"","options":["Urine concentration","Urine color only","RBC morphology","Bacterial shape"],"correctIndex":0,"explanation":"Specific gravity estimates the concentration of dissolved substances in urine.","explanationNe":"Specific gravity ले पिसाबको concentration जनाउँछ।","topic":"CSF and Body Fluid Analysis"}$json$::jsonb,true),
('bmlt-csf-bodyfluids-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',2112,$json${"question":"A positive urine nitrite test suggests:","translation":"","options":["Possible nitrate-reducing bacteria","Kidney stone composition","Low blood glucose","Liver failure"],"correctIndex":0,"explanation":"Many Gram-negative uropathogens reduce nitrate to nitrite; a negative result does not exclude infection.","explanationNe":"धेरै Gram-negative जीवाणुले nitrate लाई nitrite बनाउँछन्; negative भए पनि संक्रमण नकारिँदैन।","topic":"CSF and Body Fluid Analysis"}$json$::jsonb,true),
